import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join, dirname } from "node:path";

/**
 * Writes the conformance corpus fixture repositories.
 *
 * The fixtures are committed as files, not generated by this script at check
 * time — the corpus must be readable, diffable, and reviewable. This script
 * exists so the eight cases are authored in one place and can be re-emitted
 * deterministically, and it is run by hand when a case is added.
 */
const ROOT = "conformance/discovery/v1";

const manifest = (fields) => JSON.stringify({ name: fields.name, ...fields }, null, 2) + "\n";

const cases = {
  "minimal-package": {
    "package.json": manifest({
      name: "minimal-package",
      version: "1.0.0",
      private: true,
      packageManager: "pnpm@10.0.0",
      scripts: { test: "vitest run", build: "tsc -b", lint: "eslint ." },
      dependencies: { ajv: "^8.17.1" },
    }),
    "pnpm-lock.yaml": [
      "lockfileVersion: '9.0'",
      "",
      "settings:",
      "  autoInstallPeers: true",
      "",
      "importers:",
      "",
      "  .:",
      "    dependencies:",
      "      ajv:",
      "        specifier: ^8.17.1",
      "        version: 8.17.1",
      "",
      "packages:",
      "",
      "  ajv@8.17.1:",
      "    resolution: {integrity: sha512-fixture}",
      "",
    ].join("\n"),
    "tsconfig.json":
      JSON.stringify({ compilerOptions: { moduleResolution: "nodenext" } }, null, 2) + "\n",
    "src/index.ts": [
      'import { helper } from "./helper.js";',
      "",
      "export const value = helper(1);",
      "",
    ].join("\n"),
    "src/helper.ts": ["export const helper = (n: number): number => n + 1;", ""].join("\n"),
  },

  workspace: {
    "package.json": manifest({
      name: "workspace-root",
      private: true,
      packageManager: "pnpm@10.0.0",
      scripts: { test: "pnpm -r test" },
    }),
    "pnpm-workspace.yaml": ["packages:", "  - packages/*", ""].join("\n"),
    "pnpm-lock.yaml": [
      "lockfileVersion: '9.0'",
      "",
      "importers:",
      "",
      "  .: {}",
      "",
      "  packages/api:",
      "    dependencies:",
      "      '@scope/core':",
      "        specifier: workspace:*",
      "        version: link:../core",
      "",
      "  packages/core: {}",
      "",
    ].join("\n"),
    "packages/api/package.json": manifest({
      name: "@scope/api",
      version: "0.1.0",
      scripts: { test: "vitest run" },
      dependencies: { "@scope/core": "workspace:*" },
    }),
    "packages/core/package.json": manifest({
      name: "@scope/core",
      version: "0.1.0",
      scripts: { lint: "eslint ." },
    }),
    // A second lockfile beside a member manifest, so the snapshot carries a
    // second SCOPED package-manager fact. A package manager is a property of a
    // manifest, not of the repository, and a nested one is how that stops being
    // a claim rather than a convention.
    "packages/core/pnpm-lock.yaml": [
      "lockfileVersion: '9.0'",
      "",
      "importers:",
      "",
      "  .: {}",
      "",
    ].join("\n"),
    "packages/api/src/index.ts": [
      'import { core } from "@scope/core";',
      "export const api = core;",
      "",
    ].join("\n"),
    "packages/core/src/index.ts": ["export const core = 1;", ""].join("\n"),
  },

  "package-manager-conflict": {
    // Reduced from less/less.js at 713331655e43, which ships a pnpm lockfile
    // and an npm lockfile while declaring pnpm. That produces an `incomplete`
    // fact rather than a conflict: the declaration is carried forward and the
    // contradicting manager is published.
    "package.json": manifest({
      name: "conflicted",
      packageManager: "pnpm@9.15.9",
      dependencies: { ajv: "^8.17.1" },
    }),
    "pnpm-lock.yaml": [
      "lockfileVersion: '9.0'",
      "",
      "importers:",
      "",
      "  .:",
      "    dependencies:",
      "      ajv:",
      "        specifier: ^8.17.1",
      "        version: 8.17.1",
      "",
    ].join("\n"),
    "package-lock.json":
      JSON.stringify(
        { name: "conflicted", lockfileVersion: 3, packages: { "": { name: "conflicted" } } },
        null,
        2,
      ) + "\n",
  },

  "partial-observation": {
    "package.json": "{ this is not json\n",
    "tsconfig.json": "{ also not json\n",
  },

  "unresolved-import": {
    "package.json": manifest({ name: "unresolved", private: true }),
    "tsconfig.json":
      JSON.stringify({ compilerOptions: { moduleResolution: "nodenext" } }, null, 2) + "\n",
    "src/index.ts": [
      'import { gone } from "./gone.js";',
      'import { types } from "./types.js";',
      'import { data } from "./data.json";',
      'import { fs } from "node:fs";',
      'import { third } from "some-package";',
      "",
      "export const used = [gone, types, data, fs, third];",
      "",
    ].join("\n"),
    // Present but absent from the universe: a declaration file. Proves the
    // out-of-universe target path, which was the corpus's first defect.
    "src/types.d.ts": "export declare const types: number;\n",
    "src/data.json": '{ "a": 1 }\n',
  },

  ownership: {
    "package.json": manifest({ name: "owned", private: true }),
    // No catch-all, on purpose: without one, `scripts/` and the root package
    // are explicitly UNOWNED, which is the state that matters most and the one
    // a catch-all would hide. `packages/core/` carries two matching rules so
    // last-match-wins is observable, and the character-class rule is one this
    // version refuses, so the files beside it stay unowned rather than being
    // approximated.
    ".github/CODEOWNERS": [
      "# Two owners on one rule produce two edges.",
      "packages/api/  @org/api @alice",
      "# Two rules match packages/core; the later one wins.",
      "packages/core/  @org/default",
      "packages/core/  @org/core-late",
      "# A character class is outside the supported subset.",
      "docs/[drafts]/*  @org/docs",
      "",
    ].join("\n"),
    "packages/api/src/index.ts": ["export const api = 1;", ""].join("\n"),
    "packages/core/src/index.ts": ["export const core = 1;", ""].join("\n"),
    "docs/drafts/note.md": "# draft\n",
    "docs/published/note.md": "# published\n",
    "scripts/build.ts": ["export const build = 1;", ""].join("\n"),
  },

  "known-inaccurate-fallback-source-universe": {
    // Reduced from lodash/lodash at 2b5e6f7399a7 and webpack/webpack at
    // e95be18b4651. With no tsconfig, the deliberately blind bounded traversal
    // admits committed build output as source. KNOWN INACCURATE.
    "package.json": manifest({ name: "fallback", private: true }),
    "src/index.js": 'const helper = require("./helper.js");\nmodule.exports = { helper };\n',
    "src/helper.js": "module.exports = { helper: 1 };\n",
    "dist/index.js": 'const helper = require("./helper.js");\nmodule.exports = { helper };\n',
    "dist/helper.js": "module.exports = { helper: 1 };\n",
  },

  "unsupported-constructs": {
    // Reduced from the CommonJS findings across the corpus (express, webpack,
    // lodash, undici), plus a lockfile format this version refuses.
    "package.json": manifest({
      name: "unsupported",
      private: true,
      dependencies: { ajv: "^8.17.1" },
    }),
    "package-lock.json":
      JSON.stringify(
        {
          name: "unsupported",
          lockfileVersion: 1,
          dependencies: { ajv: { version: "8.17.1" } },
        },
        null,
        2,
      ) + "\n",
    "lib/index.js": [
      'const helper = require("./helper.js");',
      'const pkg = require("./package.json");',
      "module.exports = { helper, pkg };",
      "",
    ].join("\n"),
    "lib/helper.js": "module.exports = { helper: 1 };\n",
  },
};

rmSync(ROOT, { recursive: true, force: true });
for (const [name, files] of Object.entries(cases)) {
  for (const [path, content] of Object.entries(files)) {
    const target = join(ROOT, name, "repo", path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content, "utf8");
  }
  // No `.git` entry on disk, on purpose. Git refuses to track a path containing
  // a `.git` component at all, and a committed one would make this repository
  // treat each fixture as an embedded repository. The runner adds one in the
  // in-memory filesystem instead, so the root resolves the way a real checkout
  // does without a file in the tree that cannot be committed.
  console.log("wrote", name);
}
